import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { createHash } from 'node:crypto';
const root = process.cwd();
const ts = createRequire(path.join(root, 'package.json'))('typescript-api');
const files = execFileSync('git', ['ls-files'], { encoding: 'utf8' }).trim().split('\n');
const tracked = new Set(files);
const edges = new Map<string, string[]>();
for (const name of files.filter((name) => /\.(tsx?|css)$/.test(name))) {
  const text = fs.readFileSync(name, 'utf8');
  const imports: string[] = [];
  if (name.endsWith('.css')) {
    for (const match of text.matchAll(/@import\s+['"]([^'"]+)['"]/g)) imports.push(match[1]);
  } else {
    const source = ts.createSourceFile(name, text, ts.ScriptTarget.Latest, true);
    const visit = (node: any) => {
      if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) imports.push(node.moduleSpecifier.text);
      if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword && node.arguments[0] && ts.isStringLiteral(node.arguments[0])) imports.push(node.arguments[0].text);
      if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument) && ts.isStringLiteral(node.argument.literal)) imports.push(node.argument.literal.text);
      ts.forEachChild(node, visit);
    };
    visit(source);
  }
  edges.set(name, imports.filter((name) => name.startsWith('.')).flatMap((reference) => {
    const candidate = path.normalize(path.join(path.dirname(name), reference));
    const resolved = [candidate, candidate + '.ts', candidate + '.tsx', candidate + '/index.ts'].find((value) => tracked.has(value));
    return resolved ? [resolved] : [];
  }));
}
const target = 'src/ui/redesign/';
const roots = files.filter((name) => !name.startsWith(target) || name.endsWith('.stories.tsx'));
const reached = new Set<string>();
const walk = (name: string) => {
  if (reached.has(name)) return;
  reached.add(name);
  for (const child of edges.get(name) ?? []) walk(child);
};
for (const name of roots) walk(name);
const inventory = files.filter((name) => name.startsWith(target) && /\.(tsx?|css)$/.test(name)).map((name) => ({
  name, reachable: reached.has(name), lines: fs.readFileSync(name, 'utf8').split('\n').length - 1,
  sha256: createHash('sha256').update(fs.readFileSync(name)).digest('hex'),
  imports: edges.get(name) ?? [],
  importers: [...edges].filter(([, deps]) => deps.includes(name)).map(([name]) => name),
}));
process.stdout.write(JSON.stringify({base: execFileSync('git', ['rev-parse', 'HEAD'], {encoding: 'utf8'}).trim(), method: 'All tracked source outside redesign plus every retained story is a conservative root; TypeScript AST static imports/reexports/import types/dynamic literal imports and CSS imports form edges. Assets are retained. Inspect nonliteral and external consumers separately.', inventory}, null, 2) + '\n');

